fn add_merge_consensus(netlist: &mut Netlist) {
    use std::collections::{BTreeMap, BTreeSet};
    type Cube = BTreeMap<String, bool>;
    fn cube(signal: &str, negative: bool, inputs: &BTreeSet<String>, producers: &HashMap<String, Gate>, cache: &mut HashMap<(String, bool), Option<Cube>>) -> Option<Cube> {
        let key = (signal.to_string(), negative);
        if let Some(value) = cache.get(&key) {return value.clone();}
        let result = if inputs.contains(signal) {
            Some(BTreeMap::from([(signal.to_string(), !negative)]))
        } else if let Some(gate) = producers.get(signal) {
            match gate.kind {
                GateKind::Nor(_) if !negative => combine(&gate.inputs, true, inputs, producers, cache),
                GateKind::Or(_) if negative => combine(&gate.inputs, true, inputs, producers, cache),
                GateKind::Nor(1) if negative => cube(&gate.inputs[0], false, inputs, producers, cache),
                GateKind::Or(1) if !negative => cube(&gate.inputs[0], false, inputs, producers, cache),
                _ => None,
            }
        } else {None};
        cache.insert(key, result.clone());
        result
    }
    fn combine(signals: &[String], negative: bool, inputs: &BTreeSet<String>, producers: &HashMap<String, Gate>, cache: &mut HashMap<(String, bool), Option<Cube>>) -> Option<Cube> {
        let mut result = Cube::new();
        for signal in signals {
            for (name, value) in cube(signal, negative, inputs, producers, cache)? {
                if result.insert(name, value).is_some_and(|old| old != value) {return None;}
            }
        }
        Some(result)
    }
    fn leaves(signal: &str, producers: &HashMap<String, Gate>, seen: &mut BTreeSet<String>, result: &mut BTreeSet<String>) {
        if !seen.insert(signal.to_string()) {return;}
        if let Some(gate) = producers.get(signal).filter(|gate| gate.is_merge()) {
            for input in &gate.inputs {leaves(input, producers, seen, result);}
        } else {result.insert(signal.to_string());}
    }
    if netlist.gates.iter().any(|gate| gate.kind.is_sequential()) {return;}
    let producers: HashMap<_,_> = netlist.gates.iter().map(|gate| (gate.output.clone(),gate.clone())).collect();
    let inputs = netlist.inputs.iter().cloned().collect();
    let mut cache = HashMap::new();
    let mut terms: BTreeMap<Cube, String> = BTreeMap::new();
    let mut inverted: BTreeMap<String, String> = producers.values().filter(|gate| gate.kind == GateKind::Nor(1))
        .map(|gate| (gate.inputs[0].clone(),gate.output.clone())).collect();
    let count = netlist.gates.len();
    for index in 0..count {
        if netlist.gates[index].kind != GateKind::Or(2) || !netlist.outputs.contains(&netlist.gates[index].output) {continue;}
        if netlist.gates.iter().any(|gate| gate.inputs.contains(&netlist.gates[index].output)) {continue;}
        let mut leaf_signals = BTreeSet::new();
        leaves(&netlist.gates[index].output, &producers, &mut BTreeSet::new(), &mut leaf_signals);
        let cubes: Vec<_> = leaf_signals.iter().filter_map(|signal| cube(signal, false, &inputs, &producers, &mut cache)).collect();
        let mut candidates = BTreeSet::new();
        for (i,a) in cubes.iter().enumerate() {
            for b in &cubes[i+1..] {
                let opposite: Vec<_> = a.iter().filter(|(name,value)| b.get(*name).is_some_and(|other| other != *value)).map(|(name,_)|name.clone()).collect();
                if opposite.len() != 1 {continue;}
                let mut common = a.clone();
                common.extend(b.clone());
                common.remove(&opposite[0]);
                if common.is_empty() || common.len() > 3 {continue;}
                if cubes.iter().any(|existing| existing.iter().all(|(name,value)|common.get(name)==Some(value))) {continue;}
                candidates.insert(common);
            }
        }
        eprintln!("CONSENSUS_OPTIONS {} count={}",netlist.gates[index].output,candidates.len());
        if candidates.len() != 1 {continue;}
        let Some(common) = candidates.into_iter().next() else {continue;};
        let term = if let Some(term) = terms.get(&common) {term.clone()} else {
            let mut operands = Vec::new();
            let mut remaining = common.clone();
            let mut names: Vec<_> = producers.keys().cloned().collect();
            names.sort();
            let mut factor = None;
            for signal in names {
                if let Some(part) = cube(&signal, true, &inputs, &producers, &mut cache) {
                    if part.len() >= 2 && part.iter().all(|(name,value)| common.get(name) == Some(value))
                        && factor.as_ref().is_none_or(|(_, old): &(String,Cube)| part.len() > old.len()) {
                        factor = Some((signal, part));
                    }
                }
            }
            if let Some((signal, part)) = factor {
                eprintln!("CONSENSUS_FACTOR {} reuse={signal}",netlist.gates[index].output);
                operands.push(signal);
                for name in part.keys() {remaining.remove(name);}
            }
            for (name, positive) in &remaining {
                if !positive {operands.push(name.clone());continue;}
                let opposite = if let Some(signal) = inverted.get(name) {signal.clone()} else {
                    let signal = format!("__consensus_inv_{}", netlist.gates.len());
                    if producers.contains_key(&signal) || netlist.inputs.contains(&signal) {return;}
                    netlist.gates.push(Gate {name:signal.clone(),kind:GateKind::Nor(1),inputs:vec![name.clone()],output:signal.clone()});
                    inverted.insert(name.clone(), signal.clone());
                    signal
                };
                operands.push(opposite);
            }
            let signal = format!("__consensus_term_{}", netlist.gates.len());
            if producers.contains_key(&signal) || netlist.inputs.contains(&signal) {return;}
            netlist.gates.push(Gate {name:signal.clone(),kind:GateKind::Nor(operands.len()),inputs:operands,output:signal.clone()});
            terms.insert(common.clone(), signal.clone());
            signal
        };
        eprintln!("MERGE_CONSENSUS {} term={common:?}",netlist.gates[index].output);
        netlist.gates[index].inputs.push(term);
        netlist.gates[index].kind = GateKind::Or(3);
    }
}
